// LINEから届いたイベントから、送信先IDを取り出して見やすく表示する
const events = ($json.body && $json.body.events) || [];
if (!events.length) return [{ json: { 状態: 'イベントが空です（LINEの接続確認かもしれません）' } }];

const out = [];
for (const ev of events) {
  const s = ev.source || {};
  const row = { 種類: s.type || '不明' };
  if (s.groupId) {
    row['★ここをコピー'] = s.groupId;
    row['設定する変数'] = 'LINE_TARGET_GROUP_ID';
    row['説明'] = 'グループのIDです。社長・部長が入ったグループに送るならこれを使います。';
  } else if (s.roomId) {
    row['★ここをコピー'] = s.roomId;
    row['設定する変数'] = 'LINE_TARGET_GROUP_ID';
    row['説明'] = '複数人トークのIDです。';
  } else if (s.userId) {
    row['★ここをコピー'] = s.userId;
    row['設定する変数'] = 'LINE_TARGET_USER_ID';
    row['説明'] = '個人のIDです。1人に送るならこれを使います。';
  }
  if (ev.message && ev.message.text) row['送られたメッセージ'] = ev.message.text;
  out.push({ json: row });
}
return out;
